(()=>{let db,deck=[],i=0,first=0,answered=false;const $=s=>document.querySelector(s),shuffle=a=>{a=[...a];for(let j=a.length-1;j>0;j--){let k=Math.floor(Math.random()*(j+1));[a[j],a[k]]=[a[k],a[j]]}return a};async function init(){try{let c=new AbortController(),t=setTimeout(()=>c.abort(),8000);let r=await fetch('./knowledge.json',{signal:c.signal});clearTimeout(t);if(!r.ok)throw Error('HTTP '+r.status);db=await r.json();$('#count').textContent=db.questions.length;[...new Set(db.questions.map(q=>q.topic))].forEach(x=>$('#topic').insertAdjacentHTML('beforeend',`<option>${x}</option>`));}catch(e){$('#error').textContent='Die Wissensdatenbank konnte nicht geladen werden. Prüfe die Verbindung und lade die Seite erneut.';$('#error').classList.remove('hidden');$('#retry').classList.remove('hidden')}}function start(){let topic=$('#topic').value;deck=shuffle(db.questions.filter(q=>topic==='all'||q.topic===topic));i=first=0;$('#setup').classList.add('hidden');$('#done').classList.add('hidden');$('#quiz').classList.remove('hidden');render()}function render(){answered=false;let q=deck[i];$('#progress').textContent=`${i+1} / ${deck.length}`;$('#score').textContent=`Erstversuch: ${first}`;$('#bar').style.width=((i)/deck.length*100)+'%';let img=q.image?`<img class="visual" src="${q.image}" alt="Originalquelle: Spektraldarstellung; zur vergrößerten Ansicht anklicken" data-zoom>`:'';$('#card').innerHTML=`<div class="tag">${q.topic}</div>${img}<h2 class="question">${q.question}</h2><div class="answers">${shuffle(q.answers).map((a,n)=>`<button class="answer" data-id="${a.id}"><b>${String.fromCharCode(65+n)}</b>${a.text}</button>`).join('')}</div>`;$('#feedback').innerHTML='';$('#next').classList.add('hidden');document.querySelectorAll('.answer').forEach(b=>b.onclick=()=>choose(b,q));document.querySelector('[data-zoom]')?.addEventListener('click',e=>{let m=document.createElement('div');m.className='modal';m.innerHTML=`<img src="${e.target.src}" alt="Vergrößerte Bildquelle">`;m.onclick=()=>m.remove();document.body.append(m)})}function choose(btn,q){if(answered)return;answered=true;let ok=btn.dataset.id===q.correctAnswerId;if(ok)first++;document.querySelectorAll('.answer').forEach(b=>{b.disabled=true;if(b.dataset.id===q.correctAnswerId)b.classList.add('correct')});if(!ok){btn.classList.add('wrong');deck.push(q)}$('#feedback').innerHTML=`<div class="explain"><strong>${ok?'Richtig.':'Noch einmal merken.'}</strong> ${q.explanation}<br><small>Quelle: ${q.source}</small></div>`;$('#next').classList.remove('hidden')}function next(){i++;if(i>=deck.length){$('#quiz').classList.add('hidden');$('#done').classList.remove('hidden');$('#result').textContent=`Du hast ${first} von ${deck.length} Fragen im Erstversuch richtig beantwortet.`}else render()}$('#start').onclick=start;$('#next').onclick=next;$('#retry').onclick=()=>{$('#error').classList.add('hidden');$('#retry').classList.add('hidden');init()};$('#again').onclick=()=>{$('#done').classList.add('hidden');start()};init();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{})})();
